8	/*
9	 * Copy-first port of
10	 * node_modules/@salesforce/retail-react-app/app/components/product-view/index.jsx
11	 * (retail-react-app 10.0.0), converted to TypeScript per AGENTS.md's copy-first rule.
12	 *
13	 * Apart from the two added props described in the next paragraph, the differences from the base
14	 * file are the TypeScript annotations below, house formatting, and a small number of
15	 * optional-chaining guards that strictNullChecks requires — each flagged in place with a
16	 * `Deviation from the base file` comment.
17	 *
18	 * Per the SFCC bridge pattern in .claude/rules/overrideStyling.md, the default export stays a
19	 * faithful port with the same `forwardRef` behaviour. It carries two additive optional props
20	 * over the base file's surface, both documented on `ProductViewProps` below: `renderHeader` and
21	 * `renderVariationAttribute`. Both are behaviour-preserving when omitted — `renderHeader`
22	 * defaults to rendering the same private `ProductViewHeader` the base file renders inline, and
23	 * `renderVariationAttribute` falls through to `renderDefaultVariationAttribute`, the extracted
24	 * base per-attribute rendering. Neither name has any occurrences in the base package, so none of
25	 * the four base modules that import ProductView — product-view-modal (index and bundle),
26	 * bonus-product-view-modal, and pages/product-detail — passes either prop or is affected by
27	 * either one. (The runtime `propTypes` blocks are replaced by the TypeScript prop types; see the
28	 * note at the foot of the file.)
29	 */
30	
31	import React, { forwardRef, useEffect, useMemo, useRef, useState, useCallback } from 'react';
32	import { useLocation } from 'react-router-dom';
33	import { useIntl, FormattedMessage } from 'react-intl';
34	
35	import {
36	  Flex,
37	  Heading,
38	  Button,
39	  Skeleton,
40	  Box,
41	  Text,
42	  VStack,
43	  Fade,
44	  Stack,
45	  Radio,
46	  RadioGroup,
47	  useTheme,
48	} from '@salesforce/retail-react-app/app/components/shared/ui';
49	
50	// Constants
51	const DELIVERY_OPTIONS = {
52	  DELIVERY: 'delivery',
53	  PICKUP: 'pickup',
54	};
55	import { useCurrency, useDerivedProduct } from '@salesforce/retail-react-app/app/hooks';
56	import { useAddToCartModalContext } from '@salesforce/retail-react-app/app/hooks/use-add-to-cart-modal';
57	import { STORE_LOCATOR_IS_ENABLED } from '@salesforce/retail-react-app/app/constants';
58	import { getConfig } from '@salesforce/pwa-kit-runtime/utils/ssr-config';
59	import { useShopperBasketsV2Mutation as useShopperBasketsMutation } from '@salesforce/commerce-sdk-react';
60	import { useSFPayments, useExpressCheckoutEnabled } from '@salesforce/retail-react-app/app/hooks/use-sf-payments';
61	
62	// project components
63	import ImageGallery from '@salesforce/retail-react-app/app/components/image-gallery';
64	import Breadcrumb from '@salesforce/retail-react-app/app/components/breadcrumb';
65	import Link from '@salesforce/retail-react-app/app/components/link';
66	import withRegistration from '@salesforce/retail-react-app/app/components/with-registration';
67	import { Skeleton as ImageGallerySkeleton } from '@salesforce/retail-react-app/app/components/image-gallery';
68	import { HideOnDesktop, HideOnMobile } from '@salesforce/retail-react-app/app/components/responsive';
69	import QuantityPicker from '@salesforce/retail-react-app/app/components/quantity-picker';
70	import { useToast } from '@salesforce/retail-react-app/app/hooks/use-toast';
71	import { API_ERROR_MESSAGE } from '@salesforce/retail-react-app/app/constants';
72	import DisplayPrice from '@salesforce/retail-react-app/app/components/display-price';
73	import Swatch from '@salesforce/retail-react-app/app/components/swatch-group/swatch';
74	import SwatchGroup from '@salesforce/retail-react-app/app/components/swatch-group';
75	import { getPriceData } from '@salesforce/retail-react-app/app/utils/product-utils';
76	import PromoCallout from '@salesforce/retail-react-app/app/components/product-tile/promo-callout';
77	import SFPaymentsExpressButtons from '@salesforce/retail-react-app/app/components/sf-payments-express-buttons';
78	import { EXPRESS_BUY_NOW } from '@salesforce/retail-react-app/app/hooks/use-sf-payments';
79	import LoadingSpinner from '@salesforce/retail-react-app/app/components/loading-spinner';
80	import { useCleanupTemporaryBaskets } from '@salesforce/retail-react-app/app/hooks/use-cleanup-temporary-baskets';
81	
82	/*
83	 * These are a deliberate temporary gap, NOT evidence that no type exists — do not read them
84	 * that way. `@salesforce/retail-react-app` ships no TypeScript types (see
85	 * overrides/app/types/vendor.d.ts), but the shapes underneath are `commerce-sdk-isomorphic`'s
86	 * and it does export them: `ShopperProductsTypes.Product` / `.Variant` / `.Category`, and
87	 * `.Image` for `image` below. AGENTS.md's Type Definitions rule says to import those directly.
88	 *
89	 * Substituting them is a follow-up rather than part of this PR only because it also removes
90	 * three `no-explicit-any` warnings, moving a lint count this branch holds as an invariant
91	 * across every commit.
92	 */
93	type SfccProduct = any;
94	type SfccVariant = any;
95	type SfccCategory = any;
96	type SfccPriceData = any;
97	
98	/** One selectable value of a variation attribute, as the base hooks shape it. */
99	type SfccVariationValue = { href?: string; name: string; image?: SfccProduct; value?: string; orderable?: boolean };
100	
101	/** A variation attribute (colour, size, ...) with its selectable values. */
102	type SfccVariationAttribute = {
103	  id: string;
104	  name?: string;
105	  selectedValue?: SfccVariationValue;
106	  values: SfccVariationValue[];
107	};
108	
109	/** The per-child orderability record ProductView writes back to its parent. */
110	export type ChildProductOrderability = {
111	  showInventoryMessage?: boolean;
112	  unfulfillable?: boolean;
113	  isOutOfStock?: boolean;
114	  stockLevel?: number;
115	  productName?: string;
116	};
117	
118	export type ProductViewHeaderProps = {
119	  name?: string;
120	  currency?: string;
121	  priceData?: SfccPriceData;
122	  category?: SfccCategory[];
123	  product?: SfccProduct;
124	  isProductPartOfBundle?: boolean;
125	};
126	
127	/*
128	 * Mirrors the base file's `ProductView.propTypes` one-for-one, with the defaults declared in
129	 * the destructuring below reflected as optional. `validateOrderability`'s signature is taken
130	 * from the default implementation the base file supplies.
131	 */
132	type ProductViewProps = {
133	  product?: SfccProduct;
134	  category?: SfccCategory[];
135	  showFullLink?: boolean;
136	  imageSize?: 'sm' | 'md';
137	  isWishlistLoading?: boolean;
138	  addToCart?: ((productSelectionValues: SfccProduct[]) => unknown) | null;
139	  updateCart?: ((variant: SfccVariant, quantity: number) => unknown) | null;
140	  addToWishlist?: ((product: SfccProduct, variant: SfccVariant, quantity: number) => unknown) | null;
141	  updateWishlist?: ((product: SfccProduct, variant: SfccVariant, quantity: number) => unknown) | null;
142	  isProductLoading?: boolean;
143	  isProductPartOfSet?: boolean;
144	  isProductPartOfBundle?: boolean;
145	  childOfBundleQuantity?: number;
146	  childProductOrderability?: Record<string, ChildProductOrderability>;
147	  setChildProductOrderability?: React.Dispatch<React.SetStateAction<Record<string, ChildProductOrderability>>>;
148	  isBasketLoading?: boolean;
149	  onVariantSelected?: (product: SfccProduct, variant: SfccVariant, quantity: number) => void;
150	  validateOrderability?: (
151	    variant: SfccVariant,
152	    product: SfccProduct,
153	    quantity: number,
154	    stockLevel: number,
155	  ) => boolean | undefined;
156	  showImageGallery?: boolean;
157	  setSelectedBundleQuantity?: (quantity: number) => void;
158	  selectedBundleParentQuantity?: number;
159	  pickupInStore?: boolean;
160	  setPickupInStore?: (checked: boolean) => void;
161	  onOpenStoreLocator?: () => void;
162	  showDeliveryOptions?: boolean;
163	  customButtons?: React.ReactElement[];
164	  promotionId?: string;
165	  maxOrderQuantity?: number | null;
166	  imageGalleryFooter?: React.ReactNode;
167	  alignItems?: string;
168	  controlledVariationValues?: Record<string, string> | null;
169	  onVariationChange?: ((attributeId: string, value: string) => void) | null;
170	  /**
171	   * The one Zimmermann addition to this component's prop surface. Replaces the header block
172	   * (breadcrumb, title, price, promo callout) with caller-supplied content, receiving exactly
173	   * the values the private `ProductViewHeader` is given so a caller can reuse or ignore any of
174	   * them. Defaults to rendering that same private header, so every existing caller — cart,
175	   * wishlist, bonus-product — is byte-identical unless it opts in.
176	   *
177	   * ProductView renders the header twice (mobile and desktop breakpoints), so this is called
178	   * twice with the same arguments. Keep it pure.
179	   */
180	  renderHeader?: (props: ProductViewHeaderProps) => React.ReactNode;
181	  /**
182	   * A caller-supplied override for rendering a single variation attribute (e.g. colour,
183	   * size), receiving the full attribute object so a caller can reuse or ignore any of its
184	   * fields. Falls through to `renderDefaultVariationAttribute` — the extracted base rendering
185	   * for that attribute — via `??` at the call site. ProductView calls this once per entry in
186	   * `variationAttributes`; keep it pure.
187	   *
188	   * That `??` treats both `undefined` and `null` as absent: either return value falls through
189	   * to the base rendering for that attribute. Returning `null` is therefore NOT a way to
190	   * render nothing for that attribute — return an empty fragment if that is the intent.
191	   */
192	  renderVariationAttribute?: (attr: SfccVariationAttribute) => React.ReactNode;
193	};
194	
195	/*
196	 * The base file rebinds a function ref's `this` so the parent can reach `validateOrderability`
197	 * (see the `typeof ref === 'function'` branch below, and the set/bundle child refs in
198	 * pages/product-detail).
199	 */
200	type ProductViewRef = React.ForwardedRef<HTMLDivElement>;
201	
202	/**
203	 * The scope ProductView rebinds onto a callback `ref`, so a parent rendering set/bundle
204	 * children can reach this instance's validation. See the `typeof ref === 'function'` branch
205	 * below. A consumer names it as the `this` parameter of its ref callback —
206	 * `function (this: ProductViewRefScope, ref) { ... }` — which TypeScript accepts as a `ref`
207	 * as written; no assertion is required at the prop site.
208	 */
209	export type ProductViewRefScope = {
210	  validateOrderability: (opts: { scrollErrorIntoView: boolean }) => void;
211	};
212	
213	const ProductViewHeader = ({
214	  name,
215	  currency,
216	  priceData,
217	  category,
218	  product,
219	  isProductPartOfBundle,
220	}: ProductViewHeaderProps) => {
221	  return (
222	    <VStack mr={4} spacing={2} align="flex-start" marginBottom={[4, 4, 4, 0, 0]}>
223	      {category && (
224	        <Skeleton isLoaded={category} minWidth={64}>
225	          <Breadcrumb categories={category} />
226	        </Skeleton>
227	      )}
228	
229	      {/* Title */}
230	      <Skeleton isLoaded={name}>
231	        <Heading fontSize="2xl">{`${name}`}</Heading>
232	      </Skeleton>
233	
234	      {!isProductPartOfBundle && (
235	        <>
236	          <Skeleton isLoaded={priceData?.currentPrice}>
237	            {priceData?.currentPrice && <DisplayPrice priceData={priceData} currency={currency} />}
238	          </Skeleton>
239	
240	          <Skeleton isLoaded={product}>{product?.productPromotions && <PromoCallout product={product} />}</Skeleton>
241	        </>
242	      )}
243	    </VStack>
244	  );
245	};
246	
247	const ButtonWithRegistration = withRegistration(Button);
248	
249	/**
250	 * Render a product detail view that includes name, image gallery, price,
251	 * variant selections, action buttons
252	 */
253	
254	const ProductView = forwardRef(
255	  (
256	    {
257	      product,
258	      category,
259	      showFullLink = false,
260	      imageSize = 'md',
261	      isWishlistLoading = false,
262	      addToCart,
263	      updateCart,
264	      addToWishlist,
265	      updateWishlist,
266	      isProductLoading,
267	      isProductPartOfSet = false,
268	      isProductPartOfBundle = false,
269	      childOfBundleQuantity = 0,
270	      childProductOrderability,
271	      setChildProductOrderability,
272	      isBasketLoading = false,
273	      onVariantSelected = () => {},
274	      validateOrderability = (variant, product, quantity, stockLevel) => {
275	        if (isProductLoading) return false;
276	
277	        // If product has variations, a variant must be selected
278	        if (product?.variationAttributes?.length > 0 && !variant) {
279	          return false;
280	        }
281	
282	        // Check if product (either variant or standard) is orderable and if quantity is valid
283	        return (variant?.orderable || product?.inventory?.orderable) && quantity > 0 && quantity <= stockLevel;
284	      },
285	      showImageGallery = true,
286	      setSelectedBundleQuantity = () => {},
287	      selectedBundleParentQuantity = 1,
288	      pickupInStore = false,
289	      setPickupInStore = () => {},
290	      onOpenStoreLocator = () => {},
291	      showDeliveryOptions = true,
292	      customButtons = [],
293	      maxOrderQuantity = null,
294	      imageGalleryFooter = null,
295	      controlledVariationValues = null,
296	      onVariationChange = null,
297	      renderHeader = (headerProps: ProductViewHeaderProps) => <ProductViewHeader {...headerProps} />,
298	      renderVariationAttribute,
299	    }: ProductViewProps,
300	    ref: ProductViewRef,
301	  ) => {
302	    const { currency: activeCurrency } = useCurrency();
303	    const showToast = useToast();
304	    const intl = useIntl();
305	    const location = useLocation();
306	    const storeLocatorEnabled = getConfig()?.app?.storeLocatorEnabled ?? STORE_LOCATOR_IS_ENABLED;
307	    const {
308	      isOpen: isAddToCartModalOpen,
309	      onOpen: onAddToCartModalOpen,
310	      onClose: onAddToCartModalClose,
311	    } = useAddToCartModalContext();
312	
313	    const { mutateAsync: createBasket } = useShopperBasketsMutation('createBasket');
314	    const { mutateAsync: addItemToBasket } = useShopperBasketsMutation('addItemToBasket');
315	
316	    const theme = useTheme();
317	    const { confirmingBasket } = useSFPayments();
318	    const [showOptionsMessage, toggleShowOptionsMessage] = useState(false);
319	    const {
320	      showLoading,
321	      showInventoryMessage,
322	      inventoryMessage,
323	      quantity,
324	      minOrderQuantity,
325	      setQuantity,
326	      variant,
327	      variationParams,
328	      variationAttributes,
329	      stockLevel,
330	      stepQuantity,
331	      isOutOfStock,
332	      unfulfillable,
333	      isSelectedStoreOutOfStock,
334	      selectedStore,
335	    } = useDerivedProduct(
336	      product,
337	      isProductPartOfSet,
338	      isProductPartOfBundle,
339	      pickupInStore,
340	      controlledVariationValues,
341	      onVariationChange,
342	    );
343	    const priceData = useMemo(() => {
344	      return getPriceData(product, { quantity });
345	    }, [product, quantity]);
346	    const canAddToWishlist = !isProductLoading;
347	    const isProductASet = product?.type?.set;
348	    const isProductABundle = product?.type?.bundle;
349	    const errorContainerRef = useRef<HTMLDivElement | null>(null);
350	    const [pickupEnabled, setPickupEnabled] = useState(false);
351	    const storeName = selectedStore?.name;
352	    const inventoryId = selectedStore?.inventoryId;
353	    const { pdp: showExpressOnPDP } = useExpressCheckoutEnabled();
354	
355	    const { disableButton, customInventoryMessage } = useMemo(() => {
356	      let shouldDisableButton = showInventoryMessage;
357	      let currentInventoryMsg = '';
358	      if (!shouldDisableButton && (isProductASet || isProductABundle) && childProductOrderability) {
359	        // if any of the children are not orderable, it will disable the add to cart button
360	        const unavailableChildProductKey = Object.keys(childProductOrderability).find((key) => {
361	          return childProductOrderability[key].showInventoryMessage;
362	        });
363	        shouldDisableButton = !!unavailableChildProductKey;
364	        if (unavailableChildProductKey) {
365	          const unavailableChildProduct = childProductOrderability[unavailableChildProductKey];
366	          if (unavailableChildProduct.unfulfillable) {
367	            currentInventoryMsg = intl.formatMessage(
368	              {
369	                defaultMessage: 'Only {stockLevel} left for {productName}!',
370	                id: 'use_product.message.inventory_remaining_for_product',
371	              },
372	              {
373	                stockLevel: unavailableChildProduct.stockLevel,
374	                productName: unavailableChildProduct.productName,
375	              },
376	            );
377	          }
378	          if (unavailableChildProduct.isOutOfStock) {
379	            currentInventoryMsg = intl.formatMessage(
380	              {
381	                defaultMessage: 'Out of stock for {productName}',
382	                id: 'use_product.message.out_of_stock_for_product',
383	              },
384	              { productName: unavailableChildProduct.productName },
385	            );
386	          }
387	        }
388	      }
389	      return { disableButton: shouldDisableButton, customInventoryMessage: currentInventoryMsg };
390	    }, [showInventoryMessage, childProductOrderability]);
391	
392	    const validateAndShowError = (opts: { scrollErrorIntoView?: boolean } = {}) => {
393	      const { scrollErrorIntoView = true } = opts;
394	      // Validate that all attributes are selected before proceeding.
395	      const hasValidSelection = validateOrderability(variant, product, quantity, stockLevel);
396	      const showError = !isProductASet && !isProductABundle && !hasValidSelection;
397	      const scrollToError = showError && scrollErrorIntoView;
398	
399	      toggleShowOptionsMessage(showError);
400	
401	      if (scrollToError) {
402	        // Deviation from the base file: `?.`. The base dereferences `current` unguarded here
403	        // while guarding it in `prepareBasket` below; the two only differ if the error
404	        // container has not mounted, where the base throws.
405	        errorContainerRef.current?.scrollIntoView({
406	          behavior: 'smooth',
407	          block: 'center',
408	        });
409	      }
410	
411	      return hasValidSelection;
412	    };
413	    const cleanupTemporaryBaskets = useCleanupTemporaryBaskets();
414	
415	    // prepareBasket is used to prepare the basket for express payments
416	    // useCallback recreates prepareBasket primarily when product or quantity change, along with variant, stockLevel, and product type flags (isProductASet, isProductABundle)
417	    const prepareBasket = useCallback(async () => {
418	      // Validate that all attributes are selected before proceeding
419	      const hasValidSelection = validateOrderability(variant, product, quantity, stockLevel);
420	      let errorMessage = '';
421	
422	      if (!hasValidSelection && !isProductASet && !isProductABundle) {
423	        toggleShowOptionsMessage(true);
424	        if (errorContainerRef.current) {
425	          errorContainerRef.current.scrollIntoView({
426	            behavior: 'smooth',
427	            block: 'center',
428	          });
429	        }
430	        errorMessage = intl.formatMessage({
431	          defaultMessage: 'Please select all product options before proceeding with Express Payments',
432	          id: 'product_view.prepareBasket',
433	        });
434	
435	        const error: Error & { isValidationError?: boolean } = new Error(errorMessage);
436	        error.isValidationError = true;
437	        throw error;
438	      }
439	
440	      // Clean up temporary baskets before creating a new one
441	      await cleanupTemporaryBaskets();
442	
443	      // Create a new temporary basket
444	      const newBasket = await createBasket({
445	        parameters: {
446	          temporary: true,
447	        },
448	        body: {},
449	      });
450	
451	      const selectedProduct = variant || product;
452	      // Use variant's productId if variant is selected, otherwise use product's id
453	      const productIdToUse = selectedProduct?.productId || selectedProduct?.id;
454	
455	      if (!productIdToUse) {
456	        errorMessage = intl.formatMessage({
457	          defaultMessage: 'Unable to determine product ID for basket',
458	          id: 'product_view.prepareBasket',
459	        });
460	        throw new Error(errorMessage);
461	      }
462	      // Add the product to the temporary basket
463	      const basketWithItem = await addItemToBasket({
464	        // SDK param widening — `newBasket` is the basket just created above.
465	        parameters: { basketId: newBasket.basketId as string },
466	        body: [
467	          {
468	            productId: productIdToUse,
469	            quantity: quantity,
470	          },
471	        ],
472	      });
473	
474	      return basketWithItem;
475	    }, [variant, product, quantity, stockLevel, isProductASet, isProductABundle]);
476	
477	    const renderActionButtons = () => {
478	      const buttons = [];
479	      const buttonText = {
480	        update: intl.formatMessage({
481	          defaultMessage: 'Update',
482	          id: 'product_view.button.update',
483	        }),
484	        addToCart: intl.formatMessage({
485	          defaultMessage: 'Add to Cart',
486	          id: 'product_view.button.add_to_cart',
487	        }),
488	        addSetToCart: intl.formatMessage({
489	          defaultMessage: 'Add Set to Cart',
490	          id: 'product_view.button.add_set_to_cart',
491	        }),
492	        addBundleToCart: intl.formatMessage({
493	          defaultMessage: 'Add Bundle to Cart',
494	          id: 'product_view.button.add_bundle_to_cart',
495	        }),
496	        addToWishlist: intl.formatMessage({
497	          defaultMessage: 'Add to Wishlist',
498	          id: 'product_view.button.add_to_wishlist',
499	        }),
500	        addSetToWishlist: intl.formatMessage({
501	          defaultMessage: 'Add Set to Wishlist',
502	          id: 'product_view.button.add_set_to_wishlist',
503	        }),
504	        addBundleToWishlist: intl.formatMessage({
505	          defaultMessage: 'Add Bundle to Wishlist',
506	          id: 'product_view.button.add_bundle_to_wishlist',
507	        }),
508	      };
509	
510	      const showError = () => {
511	        showToast({
512	          title: intl.formatMessage(API_ERROR_MESSAGE),
513	          status: 'error',
514	        });
515	      };
516	
517	      const handleCartItem = async () => {
518	        const hasValidSelection = validateAndShowError();
519	
520	        if (!hasValidSelection) {
521	          return null;
522	        }
523	
524	        if (!addToCart && !updateCart) return null;
525	        if (updateCart) {
526	          await updateCart(variant || product, quantity);
527	          return;
528	        }
529	        try {
530	          // Guarded above: `!addToCart && !updateCart` returns early, and the `updateCart`
531	          // branch returns, so `addToCart` is defined here. TypeScript cannot narrow across
532	          // those two statements.
533	          const itemsAdded = await addToCart!([{ product, variant, quantity }]);
534	          // Open modal only when `addToCart` returns some data
535	          // It's possible that the item has been added to cart, but we don't want to open the modal.
536	          // See wishlist_primary_action for example.
537	          if (itemsAdded) {
538	            onAddToCartModalOpen({
539	              product,
540	              itemsAdded,
541	              selectedQuantity: quantity,
542	            });
543	          }
544	        } catch (e) {
545	          showError();
546	        }
547	      };
548	
549	      const handleWishlistItem = async () => {
550	        if (!updateWishlist && !addToWishlist) return null;
551	        if (updateWishlist) {
552	          updateWishlist(product, variant, quantity);
553	          return;
554	        }
555	        // Guarded above, exactly as `addToCart` is in handleCartItem.
556	        addToWishlist!(product, variant, quantity);
557	      };
558	
559	      // child product of bundles do not have add to cart button
560	      if ((addToCart || updateCart) && !isProductPartOfBundle) {
561	        buttons.push(
562	          <Button
563	            key="cart-button"
564	            onClick={handleCartItem}
565	            isDisabled={disableButton}
566	            isLoading={isBasketLoading}
567	            width="100%"
568	            variant="solid"
569	            marginBottom={4}
570	          >
571	            {updateCart
572	              ? buttonText.update
573	              : isProductASet
574	              ? buttonText.addSetToCart
575	              : isProductABundle
576	              ? buttonText.addBundleToCart
577	              : buttonText.addToCart}
578	          </Button>,
579	        );
580	      }
581	
582	      // child product of bundles do not have add to wishlist button
