43	import React from 'react';
44	import { describe, test, expect } from 'vitest';
45	import { render, screen } from '@testing-library/react';
46	import { ChakraProvider } from '@chakra-ui/react';
47	import { MemoryRouter } from 'react-router-dom';
48	import theme from 'app/theme';
49	import { ZimmTokensGlobal } from 'app/theme/zimmTokensGlobal';
50	import { ZimmColourSwatch } from './index';
51	
52	const IMAGE_URL = 'https://picsum.photos/seed/zimmermann-bay-blue/400/600';
53	
54	const renderSwatch = (overrides: Partial<React.ComponentProps<typeof ZimmColourSwatch>> = {}) =>
55	  render(
56	    <ChakraProvider theme={theme}>
57	      <MemoryRouter>
58	        <ZimmTokensGlobal />
59	        <ZimmColourSwatch name="Bay Blue" imageUrl={IMAGE_URL} isSelected={false} isFocusable={true} {...overrides} />
60	      </MemoryRouter>
61	    </ChakraProvider>,
62	  );
63	
64	describe('ZimmColourSwatch', () => {
65	  test('renders an anchor carrying the given href when href is present', () => {
66	    renderSwatch({ href: '/womens/dresses/natura-mini-dress/8637DS241.html?color=BAYBL' });
67	    const swatch = screen.getByRole('radio');
68	    expect(swatch.tagName).toBe('A');
69	    expect(swatch).toHaveAttribute('href', '/womens/dresses/natura-mini-dress/8637DS241.html?color=BAYBL');
70	  });
71	
72	  test('renders a plain span (not an anchor) when href is absent', () => {
73	    renderSwatch({ href: undefined });
74	    const swatch = screen.getByTestId('colour-swatch');
75	    expect(swatch.tagName).not.toBe('A');
76	  });
77	
78	  test('href-absent span carries no aria-checked when isSelected=true', () => {
79	    renderSwatch({ isSelected: true });
80	    expect(screen.getByTestId('colour-swatch')).not.toHaveAttribute('aria-checked');
81	  });
82	
83	  test('href-absent span carries no aria-checked when isSelected=false', () => {
84	    renderSwatch({ isSelected: false });
85	    expect(screen.getByTestId('colour-swatch')).not.toHaveAttribute('aria-checked');
86	  });
87	
88	  test('href-absent span carries no tabIndex when isFocusable=true', () => {
89	    renderSwatch({ isFocusable: true });
90	    expect(screen.getByTestId('colour-swatch')).not.toHaveAttribute('tabindex');
91	  });
92	
93	  test('href-absent span carries no tabIndex when isFocusable=false', () => {
94	    renderSwatch({ isFocusable: false });
95	    expect(screen.getByTestId('colour-swatch')).not.toHaveAttribute('tabindex');
96	  });
97	
98	  // Regression guard for the _focusVisible `position: relative` + `zIndex: 1` fix in
99	  // zimmColourSwatch.css.ts (SFCC-91) — without it, a focused swatch's outline ring has its
100	  // right edge painted over by the next zero-gap sibling. Only `position`/`zIndex` are
101	  // asserted here, not the rest of that `_focusVisible` block (`outline`/`outlineOffset`):
102	  // jsdom's `getComputedStyle` does reflect `position`/`zIndex` correctly once a real
103	  // `.focus()` call happens, but `outline`/`outlineOffset` themselves are a separate,
104	  // pre-existing jsdom limitation — unrelated to this fix — that this test does not attempt
105	  // to work around.
106	  // The focus-visible `position: relative` + `zIndex: 1` fix is relevant to focusable swatches
107	  // (the href branch, which carries `tabIndex`). The href-absent span is inert — it has no
108	  // `tabIndex`, so `.focus()` on it is a no-op and the `_focusVisible` block never fires.
109	  // This guard therefore uses href-branch swatches; the fix applies there and that is the only
110	  // place it matters for real users.
111	  test('focus-visible position/zIndex are not hidden by the next sibling swatch (regression guard, SFCC-91)', () => {
112	    const HREF_A = '/womens/dresses/natura-mini-dress/8637DS241.html?color=BAYBL';
113	    const HREF_B = '/womens/dresses/natura-mini-dress/8637DS241.html?color=IVORY';
114	    const { container } = render(
115	      <ChakraProvider theme={theme}>
116	        <MemoryRouter>
117	          <ZimmTokensGlobal />
118	          <div style={{ display: 'flex', gap: 0 }}>
119	            <ZimmColourSwatch name="Bay Blue" imageUrl={IMAGE_URL} isSelected={false} isFocusable={true} href={HREF_A} />
120	            <ZimmColourSwatch name="Ivory" imageUrl={IMAGE_URL} isSelected={false} isFocusable={true} href={HREF_B} />
121	          </div>
122	        </MemoryRouter>
123	      </ChakraProvider>,
124	    );
125	    const first = container.querySelectorAll('[data-testid="colour-swatch"]')[0] as HTMLElement;
126	    first.focus();
127	    const cs = getComputedStyle(first);
128	    expect(cs.position).toBe('relative');
129	    expect(cs.zIndex).toBe('1');
130	  });
131	
132	  test('renders the passed imageUrl as the swatch fill background-image', () => {
133	    renderSwatch({ imageUrl: IMAGE_URL });
134	    const swatch = screen.getByTestId('colour-swatch');
135	    const imageEl = swatch.firstElementChild as HTMLElement;
136	    expect(getComputedStyle(imageEl).backgroundImage).toContain(IMAGE_URL);
137	  });
138	
139	  test('does not set a raw CSS-colour-keyword backgroundColor from the colour name (regression guard)', () => {
140	    renderSwatch({ name: 'Bay Blue' });
141	    const swatch = screen.getByTestId('colour-swatch');
142	    // The recipe's own unconditional declaration — see the file-level comment above for why this
143	    // literal, unsubstituted form is what jsdom actually reports. A regression re-adding
144	    // `backgroundColor={name.toLowerCase()}` as an extra prop on this element would overwrite this
145	    // key in the final merged style object (Chakra assigns component style props after `__css`),
146	    // so this would read the literal "bay blue" instead — proven by an actual mutation run, not
147	    // assumed; see the PR body / step report for that run's before/after output.
148	    expect(getComputedStyle(swatch).backgroundColor).toBe('var(--zimm-color-bg-02)');
149	  });
150	});
